private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

}
private void xrLabel11_AfterPrint(object sender, System.EventArgs e) {
if (GetCurrentColumnValue("KODMONEDHA") != null)
                kodmonedha = kodmonedha + GetCurrentColumnValue("KODMONEDHA").ToString() + ";";
            if (GetCurrentColumnValue("VLERA_MONEDHE") != null)
                vleramonedha = vleramonedha + String.Format("{0:#,#.00}", GetCurrentColumnValue("VLERA_MONEDHE")) + ";";
            if (xrLabel11.Text != null && xrLabel11.Text != "")
                gjendjamonbaze = Convert.ToDouble(xrLabel11.Text);
}

private void xrLabel11_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
            {
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "0")
                {
                    if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToString() == "terheqje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToString() == "pagese")
                        progresivi = progresivi - Convert.ToDouble(GetCurrentColumnValue("VLERAMONADHABAZE"));
                    else if (GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "derdhje" || GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() == "arketim")
                        progresivi = progresivi + Convert.ToDouble(GetCurrentColumnValue("VLERAMONADHABAZE"));
                }

                xrLabel11.Text = String.Format("{0:#,#.00}", progresivi); 
            }
}

private void Detail_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (GetCurrentColumnValue("GJENDJEMBARTUR") != null)
            {
                if (GetCurrentColumnValue("GJENDJEMBARTUR").ToString() == "1")
                {
                    e.Cancel = true;
                }
            }
}

private void xrLabel1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("IDDOKUMENTI") != null)
            {
                    xrLabel1.NavigateUrl = "javascript:window.parent.myFaqeCelje.hapFaqeNeTabTeRi('ShtoVeprimBanka.aspx?scopeID="+scopeID+"&newScopeId=True&lloji=" + GetCurrentColumnValue("LLOJIVEPRIMIT").ToString().ToLower() + "&id=" + GetCurrentColumnValue("IDDOKUMENTI").ToString() + "&numer=" + GetCurrentColumnValue("NRDOKUMENTI").ToString() + "&shtim_modifikim=modifikim')";
                    xrLabel1.ForeColor = Color.SteelBlue;
			  xrLabel1.Target = "_self";


            }
}

private void xrLabel21_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 xrLabel21.Text = String.Format("{0:#,#.00}",gjendjamonbaze);
}

private void ReportFooter_AfterPrint(object sender, System.EventArgs e) {
 kodmonedha = "";
            vleramonedha = "";
            progresivi = 0.00;
}

private void ReportFooter_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
System.Resources.ResourceManager rm = new System.Resources.ResourceManager("Resources.Strings",
                       System.Reflection.Assembly.Load("App_GlobalResources")); 
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);

 float koordinataY = 0F;
            string[] split = { ";" };
            string[] monedha = kodmonedha.Split(';');
            string[] vlerat = vleramonedha.Split(';');
            for (int i = 0; i < monedha.Length; i++)
            {
                if (monedha[i] != "")
                {
                    XRLabel emermonedhe = new XRLabel();
                    emermonedhe.LocationFloat = new DevExpress.Utils.PointFloat(koordinataX, koordinataY);
                    emermonedhe.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);
                    emermonedhe.Name = "emermonedhe" + i;
                    emermonedhe.SizeF = new System.Drawing.SizeF(159.15F, 20F);
                    emermonedhe.Text = rm.GetString("labelFilterAvancuarGjendja", parametraRaporti.Ci) + ":" + monedha[i];
                    XRLabel vleramonedhe = new XRLabel();
                    vleramonedhe.LocationFloat = new DevExpress.Utils.PointFloat(koordinataLlogariX, koordinataY);
                    vleramonedhe.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);
                    vleramonedhe.Name = "vleramonedhe" + i;
                    vleramonedhe.SizeF = new System.Drawing.SizeF(191.06F, 20F);
                    vleramonedhe.Text = vlerat[i];
                    if (nr == 0)
                        this.xrPanel2.Controls.AddRange(new DevExpress.XtraReports.UI.XRControl[] { emermonedhe, vleramonedhe });
                    koordinataY += distancaLartesi;
                }
            }
            nr++;
}

